DROP TABLE IF EXISTS `ideas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ideas` (
  `ideaID` int unsigned NOT NULL AUTO_INCREMENT,
  `userID` int unsigned NOT NULL,
  `creatorID` int unsigned DEFAULT NULL,
  `ideaTitle` varchar(255) NOT NULL,
  `ideaImage` varchar(255) DEFAULT NULL,
  `portfolioID` varchar(10) DEFAULT NULL,
  `similarID` varchar(10) DEFAULT NULL,
  `isModerated` tinyint NOT NULL DEFAULT '0',
  `isHomeIdea` tinyint NOT NULL DEFAULT '0',
  `isArchived` tinyint NOT NULL DEFAULT '0',
  `position` int DEFAULT NULL,
  `timestamp` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ideaID`),
  KEY `userToIdea` (`userID`),
  CONSTRAINT `userToIdea` FOREIGN KEY (`userID`) REFERENCES `users` (`userID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3821 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

