ps://basementremodeling.com/public/upload/ideas/3811/DSC_4645','346','0',0,0,0,NULL,'2025-01-28 05:27:42'),(3812,47,9,'Modern Basement Remodel with Wet Bar, Fireplace, and Gym','https://basementremodeling.com/public/upload/ideas/3812/DSC_4630','346','0',0,0,0,NULL,'2025-01-28 05:27:42'),(3813,47,9,'Modern Basement Remodel with Wet Bar, Fireplace, and Gym','https://basementremodeling.com/public/upload/ideas/3813/DSC_4651','346','0',0,0,0,NULL,'2025-01-28 05:27:42'),(3814,47,9,'Modern Basement Remodel with Wet Bar, Fireplace, and Gym','https://basementremodeling.com/public/upload/ideas/3814/DSC_4658','346','0',0,0,0,NULL,'2025-01-28 05:27:42'),(3815,47,9,'Modern Basement Remodel with Wet Bar, Fireplace, and Gym','https://basementremodeling.com/public/upload/ideas/3815/DSC_4615','346','0',0,0,0,NULL,'2025-01-28 05:27:42'),(3816,47,9,'Modern Basement Remodel with Wet Bar, Fireplace, and Gym','https://basementremodeling.com/public/upload/ideas/3816/DSC_4673','346','0',0,0,0,NULL,'2025-01-28 05:27:42'),(3817,47,9,'Modern Basement Remodel with Wet Bar, Fireplace, and Gym','https://basementremodeling.com/public/upload/ideas/3817/DSC_4677','346','0',0,0,0,NULL,'2025-01-28 05:27:42'),(3818,47,9,'Modern Basement Remodel with Wet Bar, Fireplace, and Gym','https://basementremodeling.com/public/upload/ideas/3818/DSC_4683','346','0',0,0,0,NULL,'2025-01-28 05:27:42'),(3819,47,9,'Modern Basement Remodel with Wet Bar, Fireplace, and Gym','https://basementremodeling.com/public/upload/ideas/3819/DSC_4685','346','0',0,0,0,NULL,'2025-01-28 05:27:42'),(3820,47,9,'Modern Basement Remodel with Wet Bar, Fireplace, and Gym','https://basementremodeling.com/public/upload/ideas/3820/DSC_4688','346','0',0,0,0,NULL,'2025-01-28 05:27:42');
