INSERT INTO `settings` VALUES (1,'877-224-2434','301-798-4444','443-424-2425','703-270-0141','202-410-0111','1680 E Gude dr, STE 313, Rockville, MD, 20850','contacts@basementremodeling.com','contacts@basementremodeling.com','MONDAY-FRIDAY:','8:00 AM - 12:00 AM','SAT, SUN - CLOSED','https://www.instagram.com/basement_remodeling_com/','https://www.facebook.com/BasementRemodelingCom/','https://www.pinterest.ru/basementmasters/','https://member.angieslist.com/member/store/2346351/','https://www.houzz.com/professionals/general-contractors/basement-masters-pfvwus-pf~847553638','https://search.google.com/local/writereview?placeid=ChIJbSYsElAGyIkRh36j6z1FtFc','https://www.facebook.com/pg/BasementRemodelingCom/reviews/','https://porch.com/rockville-md/remodeling-contractors/basement-remodeling-company-164612476/pp','','The copyright in this website and the material on this website (including without limitation the text, artwork, photographs, images, music, audio material, video material and audio-visual material on this website) is owned by Basement Masters and its licensors.','smtp.gmail.com','465','true','contacts@basementremodeling.com','bmasters2020','BasementRemodeling.com contacts@basementremodeling.com','Thank you for submitting your request','New request from website','https://hook.integromat.com/w9mqz38sovmwcyx9hvgovb5zh6kjyz5u','https://hook.integromat.com/wn8bpdyn5smvlc1eo3c13kb9f4lyk9ah');
